import React, { useState, useEffect } from "react";
import "assets/landing/css/login.css";
import ConectTextLogo from "assets/img/logo/ConectTextLogo";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import LoginToast from "variables/Toast/LoginToast";
import { useDispatch } from "react-redux";
import { LOGIN } from "../Redux/Reducer/userDataReducer";
import { SET_DPARTINFO } from "../Redux/Reducer/departDataReducer";
import LoginModal from "variables/Modal/LoginModal";

//이 컴포넌트는 메인 페이지를 세팅하는 컴포넌트입니다.

const Login = (props) => {
  const dispatch = useDispatch();
  const [isFirst, setIsFirst] = useState(true); //첫 렌더링 여부
  const [isSignIn, setIsSignIn] = useState(null); //로그인/문의 토글용
  const [loginInfo, setLoginInfo] = useState({
    comp_pk_num: "",
    user_pk_num: "",
    user_pw: "",
  });
  const [errType, setErrType] = useState(0); //로그인 실패시 에러타입 설정
  const [data, setData] = useState({}); //로그인 성공시 데이터 저장
  const navigate = useNavigate();
  const [isReversed, setIsReversed] = useState(false); //로그인 성공시 역방향 트랜스폼

  const toggle = () => {
    setIsSignIn((prev) => !prev);
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsFirst(false);
      setIsSignIn(true);
    }, 200);

    // 클린업 함수: 컴포넌트 언마운트 시 타이머 정리
    return () => clearTimeout(timer);
  }, []); // 빈 배열로 수정

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLoginInfo({
      ...loginInfo,
      [name]: value,
    });
  };

  //부트스트랩 토스트 토글용
  const [showA, setShowA] = useState(false);
  const toggleShowA = () => {
    setShowA(true);
    setTimeout(() => {
      setShowA(false);
    }, 3000);
  };

  //부트스트래  모달 토글용
  const [showM, setShowM] = useState(false);
  const handleShowM = () => setShowM(true); //모달을 열어주는 함수
  const handleCloseM = () => setShowM(false); //모달을 닫는 함수

  const login = async (e) => {
    e.preventDefault();
    try {
      let res = await axios.post("/login", loginInfo);
      const responseData = res.data;
      await setData(responseData);
      if (res.data.status === 1) {
        //로그인 성공
        dispatch(LOGIN(responseData));
        let dpartsInfo = await axios.get("/login/departs");
        dispatch(SET_DPARTINFO(dpartsInfo.data));
        setIsReversed(true); // 역방향 트랜스폼 적용
        setTimeout(() => {
          navigate(`/ProjSel/${loginInfo.user_pk_num}`);
        }, 1000); // 트랜지션 시간에 맞춰 조정
      } else if (res.data.status === 2) {
        //로그인 실패(정보 불일치)
        setErrType(res.data.status);
        toggleShowA();
      } else if (res.data.status === 3) {
        //잠긴계정
        setErrType(res.data.status);
        handleShowM();
      }
    } catch (error) {
      console.error("로그인 실패:", error);
    }
  };

  return (
    <>
      <div
        className={`login-container ${
          isFirst ? "" : isSignIn ? "sign-in" : "sign-up"
        } ${isReversed ? "reverse" : ""}`}
      >
        <div className="row">
          <div className="col align-items-center flex-col sign-up">
            <h2>비밀번호를 잊으셨나요?</h2>
            <div className="form-wrapper align-items-center">
              <div className="form sign-up">
                <p>
                  <button className="button">관리자에게 연락하기</button>
                  <b onClick={() => toggle()} className="pointer">
                    로그인하기
                  </b>
                </p>
              </div>
            </div>
          </div>
          <div className="col align-items-center flex-col sign-in">
            <ConectTextLogo />
            {/* <h3 style={{ color: "#255260" }}>어서오세요. 코난2조 입니다.</h3> */}
            <form onSubmit={(e) => login(e)}>
              <div className="form-wrapper align-items-center">
                <div className="form sign-in">
                  <div className="input-group">
                    <i className="bx bxs-com-num"></i>
                    <input
                      type="number"
                      placeholder="회사번호"
                      name="comp_pk_num"
                      value={loginInfo.comp_pk_num}
                      onChange={(e) => handleChange(e)}
                      required
                    />
                  </div>
                  <div className="input-group">
                    <i className="bx bxs-user"></i>
                    <input
                      type="number"
                      placeholder="사번"
                      name="user_pk_num"
                      value={loginInfo.user_pk_num}
                      onChange={(e) => handleChange(e)}
                      required
                    />
                  </div>
                  <div className="input-group">
                    <i className="bx bxs-lock-alt"></i>
                    <input
                      type="password"
                      placeholder="비밀번호"
                      name="user_pw"
                      value={loginInfo.user_pw}
                      onChange={(e) => handleChange(e)}
                      required
                    />
                    <button type="submit" className="button">
                      로그인
                    </button>
                  </div>
                  <p>
                    <b onClick={() => toggle()} className="pointer">
                      비밀번호를 잊으셨나요?
                    </b>
                  </p>
                </div>
              </div>
            </form>
          </div>
        </div>
        <div className="form-wrapper"></div>
        <div className="row content-row">
          <div className="col align-items-center flex-col">
            <div className="text sign-in">
              <h2>Welcome</h2>
            </div>
            <div className="img sign-in"></div>
          </div>
          <div className="col align-items-center flex-col">
            <div className="text sign-up">
              <h2>&emsp; Contact</h2>
            </div>
          </div>
        </div>
      </div>
      <LoginToast
        showA={showA}
        toggleShowA={toggleShowA}
        type={errType}
        data={data}
      />
      <LoginModal
        handleCloseM={handleCloseM}
        handleShowM={handleShowM}
        showM={showM}
        type={errType}
      />
    </>
  );
};

export default Login;
